// TestReadPDF_RealManifest carries the JPEG fixture's own manifest store in a
// synthetic PDF and reads it back, proving the PDF carrier feeds the same
// parser: the surfaced Info must be what the JPEG yields.
func TestReadPDF_RealManifest(t *testing.T) {
	data, err := os.ReadFile("testdata/c2pa_signed.jpg")
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	want := Read(ctx, JPEG, bytes.NewReader(data))
	if !want.Present {
		t.Fatal("fixture has no manifest")
	}
	doc := synthPDF(t, extractJUMBF(ctx, JPEG, data), true)
	if got := Read(ctx, PDF, bytes.NewReader(doc)); got != want {
		t.Fatalf("Read(PDF) = %+v\nwant %+v", got, want)
	}
}

// TestValidatePDF_ProducerShapes validates a generated PDF whose carrier uses
// the four shapes an observed producer emits and the corpus's own PDF case does
// not — each on a different branch of the scan: the generation number in the
// object header and in /Root, /Type spelled /FileSpec, a /Subtype read by
// pdfText's literal-string branch rather than as a name, and a manifest that
// only the incremental update section associates.
func TestValidatePDF_ProducerShapes(t *testing.T) {
	spec := func(sb *signerBundle) manifestSpec {
		return manifestSpec{signer: sb, assertions: []assertionSpec{markerAssertion()}}
	}

	t.Run("catalog chain", func(t *testing.T) {
		sb := newCorpusSigner(t, cose.AlgorithmES256)
		asset := buildFramedAsset(t, pdfProducerFraming(true), spec(sb))
		for shape, want := range map[string]string{
			"catalog at generation 1": "/Root 5 1 R",
			"capital-S file spec":     "/Type /FileSpec",
			"literal-string subtype":  "/Subtype (application/c2pa)",
			"incremental update":      "/Prev ",
		} {
			if !bytes.Contains(asset, []byte(want)) {
				t.Fatalf("%s: asset does not carry %q", shape, want)
			}
		}
		assertPDFProducerValid(t, asset, sb)
	})

	// The chain resolving is what keeps /Subtype off the path above, so the
	// literal-string branch only carries a document whose chain is compressed
	// out of sight.
	t.Run("literal subtype alone", func(t *testing.T) {
		sb := newCorpusSigner(t, cose.AlgorithmES256)
		ctx := context.Background()
		asset := buildFramedAsset(t, pdfProducerFraming(false), spec(sb))
		if bytes.Contains(asset, []byte(pdfC2PARelationship)) {
			t.Fatal("asset still carries the relationship marker")
		}
		if _, _, src := pdfScan(ctx, asset); src != pdfStoreMarker {
			t.Fatal("the catalog still associates a store, so /Subtype is not the route")
		}
		assertPDFProducerValid(t, asset, sb)
	})
}

func assertPDFProducerValid(t *testing.T, asset []byte, sb *signerBundle) {
	t.Helper()
	res := runCorpus(t, PDF, asset, sb)
	if !res.Valid {
		t.Fatalf("expected valid, got %v", codes(res))
	}
	for _, want := range []StatusCode{
		StatusClaimSignatureValidated,
		StatusSigningCredentialTrusted,
		StatusAssertionHashedURIMatch,
		StatusAssertionDataHashMatch,
	} {
		if !res.Has(want) {
			t.Errorf("missing %s; got %v", want, codes(res))
		}
	}
}

// TestValidatePDF_ReportsUnevaluatedStores pins that a document signed twice
// says so: §A.4.2.1 asks a consumer to process every update section's store as
// one, and only the active one is evaluated here.
func TestValidatePDF_ReportsUnevaluatedStores(t *testing.T) {
	pool, data := fixtureSigningPool(t)
	ctx := context.Background()
	store := extractJUMBF(ctx, JPEG, data)

	one := synthPDF(t, store, false)
	if got := pdfTallyStores(ctx, one, indexPDFObjects(ctx, one)); got.total != 1 {
		t.Fatalf("single-store document counted %d stores", got.total)
	}
	two := newPDFDoc().
		obj(1, "<< /Type /Catalog /AF [3 0 R] >>").
		obj(3, pdfC2PAFilespec).
		stream(4, pdfEmbeddedFileDict, store, "").
		trailer(1).
		obj(1, "<< /Type /Catalog /AF [5 0 R] >>").
		obj(5, "<< /AFRelationship /C2PA_Manifest /EF << /F 6 0 R >> >>").
		stream(6, pdfEmbeddedFileDict, store, "").
		trailer(1).bytes()
	// Two sections, one store each: §A.4.2.1's unmerged case, not §15.5.2.2's
	// invalid one.
	got := pdfTallyStores(ctx, two, indexPDFObjects(ctx, two))
	if got.total != 2 || got.perSection != 1 {
		t.Fatalf("re-signed document tallied %+v, want total 2 across one-store sections", got)
	}

	r := Validate(ctx, PDF, bytes.NewReader(two), WithSigningTrust(pool))
	if !r.Has(StatusUnsupported) {
		t.Errorf("expected an informational status for the store not evaluated: %+v", r.Statuses)
	}
	if !r.Has(StatusClaimSignatureValidated) {
		t.Errorf("active manifest's signature not validated: %+v", r.Statuses)
	}
}

// TestValidatePDF_MultipleStoresInOneSection pins §15.5.2.2: multiple manifest
// stores in a single update section "shall all be considered as invalid and the
// validation should treat this as if no manifests were located". Recording that
// informationally left Valid true and still surfaced one of them.
func TestValidatePDF_MultipleStoresInOneSection(t *testing.T) {
	pool, data := fixtureSigningPool(t)
	ctx := context.Background()
	store := extractJUMBF(ctx, JPEG, data)

	doc := newPDFDoc().
		obj(1, "<< /Type /Catalog /AF [3 0 R 5 0 R] >>").
		obj(3, pdfC2PAFilespec).
		stream(4, pdfEmbeddedFileDict, store, "").
		obj(5, "<< /Type /Filespec /AFRelationship /C2PA_Manifest /EF << /F 6 0 R >> >>").
		stream(6, pdfEmbeddedFileDict, store, "").
		xrefTrailer(1).bytes()

	r := Validate(ctx, PDF, bytes.NewReader(doc), WithSigningTrust(pool))
	if r.Valid {
		t.Errorf("two stores in one update section validated: %v", codes(r))
	}
	if !r.Has(StatusClaimMissing) {
		t.Errorf("expected %s, treating it as if no manifest were located: %v",
			StatusClaimMissing, codes(r))
	}
	if r.Has(StatusClaimSignatureValidated) {
		t.Errorf("a store was still surfaced and verified: %v", codes(r))
	}
}

// TestValidatePDF_StoreCountSeesMarkedStores pins that the counter considers the
// same candidates the extractor would. Counting only file specifications whose
// /AFRelationship is C2PA_Manifest reported 0 for /Subtype-only stores, so the
// signal went silent exactly where the extractor is least sure of itself.
func TestValidatePDF_StoreCountSeesMarkedStores(t *testing.T) {
	pool, data := fixtureSigningPool(t)
	ctx := context.Background()
	store := extractJUMBF(ctx, JPEG, data)

	// No catalog is visible and neither stream carries a relationship, so
	// /Subtype is all there is to go on — and there are two of them.
	doc := newPDFDoc().
		stream(4, pdfEmbeddedFileDict, store, "").
		stream(6, pdfEmbeddedFileDict, store, "").
		trailer(1).bytes()

	r := Validate(ctx, PDF, bytes.NewReader(doc), WithSigningTrust(pool))
	for _, s := range r.Statuses {
		if s.Code == StatusUnsupported && strings.Contains(s.Explanation, "not evaluated") {
			return
		}
	}
	t.Errorf("two /Subtype-only stores reported none unevaluated: %+v", r.Statuses)
}

// TestValidatePDF_AttachmentIsNotASecondStore pins the symmetric case: an
// embedded file carrying its own object-level manifest (§A.4.3) is associated
// from the object it describes, not from a catalog, so it is not a second store
// of this document and must not raise a status.
func TestValidatePDF_AttachmentIsNotASecondStore(t *testing.T) {
	pool, data := fixtureSigningPool(t)
	ctx := context.Background()
	store := extractJUMBF(ctx, JPEG, data)

	doc := newPDFDoc().
		obj(1, "<< /Type /Catalog /AF [3 0 R] >>").
		obj(3, pdfC2PAFilespec).
		stream(4, pdfEmbeddedFileDict, store, "").
		obj(7, "<< /Type /Filespec /F (image.jpg) /AFRelationship /C2PA_Manifest"+
			" /EF << /F 8 0 R >> >>").
		stream(8, pdfEmbeddedFileDict, store, "").
		xrefTrailer(1).bytes()

	r := Validate(ctx, PDF, bytes.NewReader(doc), WithSigningTrust(pool))
	if !r.Has(StatusClaimSignatureValidated) {
		t.Fatalf("the document's own store was not evaluated: %v", codes(r))
	}
	for _, s := range r.Statuses {
		if s.Code == StatusUnsupported && strings.Contains(s.Explanation, "not evaluated") {
			t.Errorf("an attachment's manifest counted as a second store: %q", s.Explanation)
		}
	}
}

// pdfTwoSectionFraming puts a constant store in the base section and the signed
// one in an incremental update, so the document carries a store this extractor
// does not evaluate while the active manifest is still the signed one. The base
// section's bytes never change, which keeps the exclusion fixpoint stable.
func pdfTwoSectionFraming(store []byte) (asset []byte, exclStart, exclLen int) {
	earlier := synthJUMB([]byte("an earlier update section's store"))
	asset = append(asset, "%PDF-1.7\n"...)
	asset = append(asset, "1 0 obj\n<< /Type /Catalog /AF [3 0 R] >>\nendobj\n"...)
	asset = append(asset, "3 0 obj\n<< /Type /Filespec /AFRelationship /C2PA_Manifest"+
		" /EF << /F 4 0 R >> >>\nendobj\n"...)
	asset = append(asset, fmt.Sprintf("4 0 obj\n<< /Type /EmbeddedFile /Length %d >>\nstream\n",
		len(earlier))...)
	asset = append(asset, earlier...)
	asset = append(asset, "\nendstream\nendobj\ntrailer\n<< /Root 1 0 R >>\nstartxref\n0\n%%EOF\n"...)

	asset = append(asset, "1 0 obj\n<< /Type /Catalog /AF [5 0 R] >>\nendobj\n"...)
	asset = append(asset, "5 0 obj\n<< /Type /Filespec /AFRelationship /C2PA_Manifest"+
		" /EF << /F 6 0 R >> >>\nendobj\n"...)
	asset = append(asset, fmt.Sprintf("6 0 obj\n<< /Type /EmbeddedFile /Length %d >>\nstream\n",
		len(store))...)
	exclStart = len(asset)
	asset = append(asset, store...)
	exclLen = len(asset) - exclStart
	asset = append(asset, "\nendstream\nendobj\ntrailer\n<< /Root 1 0 R >>\nstartxref\n0\n%%EOF\n"...)
	return asset, exclStart, exclLen
}

// TestValidatePDF_CrossStoreIngredientIsNotAMismatch pins that an ingredient
// naming a manifest in an update section this extractor did not evaluate is not
// reported as a mismatch. §A.4.2.1 permits the reference and asks a consumer to
// process every store as one; only the active store is parsed here, so an absent
// manifest is unproven, not wrong.
func TestValidatePDF_CrossStoreIngredientIsNotAMismatch(t *testing.T) {
	sb := newCorpusSigner(t, cose.AlgorithmES256)
	asset := buildFramedAsset(t, pdfTwoSectionFraming, manifestSpec{
		signer: sb,
		assertions: []assertionSpec{
			markerAssertion(),
			{label: "c2pa.ingredient", raw: ingredientAssertion(t, "urn:in-an-earlier-section").data},
		},
	})

	ctx := context.Background()
	tally := pdfTallyStores(ctx, asset, indexPDFObjects(ctx, asset))
	if tally.total != 2 {
		t.Fatalf("framing did not produce two stores: %+v", tally)
	}

	res := runCorpus(t, PDF, asset, sb)
	if res.Has(StatusIngredientManifestMismatch) {
		t.Errorf("cross-store ingredient reported as a mismatch: %v", codes(res))
	}
	if !res.Valid {
		t.Errorf("expected valid, got %v", codes(res))
	}
}

// TestValidatePDF_VerifiesSignature runs the full validator over a PDF carrying
// the fixture's manifest. The hard binding legitimately mismatches — the
// fixture's c2pa.hash.data exclusions describe the JPEG it was signed over, not
// this document — so the assertion is that the signature step ran and passed.
func TestValidatePDF_VerifiesSignature(t *testing.T) {
	pool, data := fixtureSigningPool(t)
	ctx := context.Background()
	doc := synthPDF(t, extractJUMBF(ctx, JPEG, data), true)

	r := Validate(ctx, PDF, bytes.NewReader(doc),
		WithSigningTrust(pool), WithTimestampTrust(fixtureTimestampPool(t)))
	if !r.Has(StatusClaimSignatureValidated) {
		t.Fatalf("signature not validated through the PDF carrier: %+v", r.Statuses)
	}
	if r.Info.Title != "CA.jpg" {
		t.Errorf("Info.Title = %q want CA.jpg", r.Info.Title)
	}
	if !r.Has(StatusAssertionDataHashMismatch) {
		t.Errorf("expected the fixture's data hash to mismatch in a PDF: %+v", r.Statuses)
	}
}

// buildUnterminatedStreams produces n stream objects that each carry an
// indirect /Length and never close with `endobj` — the shape that makes the
// repair pass re-scan to end of file once per object.
func buildUnterminatedStreams(n int) []byte {
	var b bytes.Buffer
	b.WriteString("%PDF-1.7\n")
	b.WriteString("1 0 obj\n5\nendobj\n")
	for i := range n {
		fmt.Fprintf(&b, "%d 0 obj\n<< /Length 1 0 R >>\nstream\nAAAAA\nendstream\n", i+10)
	}
	b.WriteString("trailer\n<< /Root 99 0 R >>\nstartxref\n0\n%%EOF\n")
	return b.Bytes()
}

// TestPDFEndObjIsBounded pins the property directly, without depending on a
// clock. pdfEndObj is called once per repaired object, so an unbounded search
// costs a full pass over the input each time.
func TestPDFEndObjIsBounded(t *testing.T) {
	data := bytes.Repeat([]byte("A"), 4*maxPDFEndObjScan) // no `endobj` anywhere
	if got := pdfEndObj(data, 0); got > maxPDFEndObjScan {
		t.Errorf("pdfEndObj scanned to %d with no keyword present; must stop at %d", got, maxPDFEndObjScan)
	}
	// It must still find a keyword that is genuinely inside the window, which is
	// where every conforming document puts it.
	withKeyword := append(bytes.Repeat([]byte("A"), 100), "endobj"...)
	if got := pdfEndObj(withKeyword, 0); got != 100 {
		t.Errorf("pdfEndObj = %d, want 100 — the keyword is well inside the window", got)
	}
}

// TestPDFRepairCostStaysLinear is the canary for the whole repair path, not just
// pdfEndObj: any future full-input scan added per object shows up here.
// Before the bound, 4k to 16k objects went from 108ms to 1.7s — 16x for 4x the
// work. c2pa-inspector validates with context.Background(), so there is no
// deadline to cut such a case short; the browser tab simply stops.
// TestPDFRepairCostStaysLinear pins the bound on pdfEndObj. Resolving an
// indirect /Length re-cuts the object, and finding its `endobj` by scanning to
// end of file costs one full pass per repaired object. A document that omits
// the keyword turns that into quadratic work: before the bound, quadrupling the
// objects from 8k to 32k took 440ms to 6.9s, and a 16 MiB input ran for minutes.
// c2pa-inspector validates with context.Background(), so there is no deadline
// to cut it short — the browser tab simply stops.
func TestPDFRepairCostStaysLinear(t *testing.T) {
	const small, factor = 4000, 4

	measure := func(n int) time.Duration {
		data := buildUnterminatedStreams(n)
		start := time.Now()
		pdfJUMBF(context.Background(), data)
		return time.Since(start)
	}
	// Best of three: a loaded machine inflates individual samples, and the
	// minimum is the one least polluted by whatever else is running.
	best := func(n int) time.Duration {
		d := measure(n)
		for range 2 {
			d = min(d, measure(n))
		}
		return d
	}
	base, scaled := best(small), best(small*factor)

	// Linear grows by `factor` (4x), quadratic by factor squared (16x). The
	// midpoint separates them with headroom on both sides.
	const tolerated = factor * 2
	if scaled > base*tolerated {
		t.Errorf("scaling %dx the objects took %.1fx the time (%v -> %v); the repair pass looks quadratic again",
			factor, float64(scaled)/float64(max(base, time.Microsecond)), base, scaled)
	}
	t.Logf("%d objects %v; %d objects %v", small, base.Round(time.Millisecond), small*factor, scaled.Round(time.Millisecond))
}
